<?php
declare(strict_types=1);namespace App\Services;
use App\Config\Database;use App\Support\Reference;use PDO;use RuntimeException;
final class FinanceService{
 private static function finance(string$p):void{if(!Auth::can($p))throw new RuntimeException('Finance permission required.');}
 private static function base():string{return"SELECT p.*,sh.shipment_ref,sh.load_id,l.load_ref,c.display_name payer_name,a.carrier_company_id,a.carrier_user_id,cc.display_name carrier_name,bo.offered_amount_tzs,s.settlement_id,s.settlement_ref,s.gross_amount,s.deduction_amount,s.net_amount,s.settlement_status,po.payout_status,po.transaction_reference payout_reference FROM payments p JOIN shipments sh ON sh.shipment_id=p.shipment_id JOIN loads l ON l.load_id=sh.load_id LEFT JOIN companies c ON c.company_id=p.payer_company_id LEFT JOIN assignments a ON a.assignment_id=sh.active_assignment_id LEFT JOIN companies cc ON cc.company_id=a.carrier_company_id LEFT JOIN bids_offers bo ON bo.offer_id=a.accepted_offer_id LEFT JOIN settlements s ON s.payment_id=p.payment_id LEFT JOIN payouts po ON po.settlement_id=s.settlement_id";}
 public static function eligible():array{self::finance('PAYMENT_MANAGE_FINANCE');return Database::connection()->query("SELECT sh.shipment_id,sh.shipment_ref,l.load_ref,l.customer_company_id,c.display_name,bo.offered_amount_tzs FROM shipments sh JOIN loads l ON l.load_id=sh.load_id JOIN companies c ON c.company_id=l.customer_company_id LEFT JOIN assignments a ON a.assignment_id=sh.active_assignment_id LEFT JOIN bids_offers bo ON bo.offer_id=a.accepted_offer_id LEFT JOIN payments p ON p.shipment_id=sh.shipment_id WHERE sh.current_status='delivered' AND p.payment_id IS NULL ORDER BY sh.delivered_at")->fetchAll();}
 public static function all():array{self::finance('PAYMENT_VIEW_FINANCE');return Database::connection()->query(self::base()." ORDER BY p.created_at DESC")->fetchAll();}
 public static function shipper(int$company):array{if(!Auth::can('PAYMENT_VIEW_SHIPPER'))throw new RuntimeException('Payment permission required.');$st=Database::connection()->prepare(self::base()." WHERE p.payer_company_id=? ORDER BY p.created_at DESC");$st->execute([$company]);return$st->fetchAll();}
 public static function carrier(int$uid):array{if(!Auth::can('SETTLEMENT_VIEW_CARRIER'))throw new RuntimeException('Settlement permission required.');$p=CarrierOnboarding::current($uid);if(!$p)return[];$col=$p['owner_type']==='company'?'s.carrier_company_id':'s.carrier_user_id';$val=$p['owner_type']==='company'?(int)$p['subject_id']:$uid;$st=Database::connection()->prepare(self::base()." WHERE {$col}=? ORDER BY s.created_at DESC");$st->execute([$val]);return$st->fetchAll();}
 public static function createPayment(int$shipment,float$amount,string$currency,string$due,int$uid):void{self::finance('PAYMENT_MANAGE_FINANCE');if($amount<=0||!preg_match('/^[A-Z]{3}$/',$currency))throw new RuntimeException('Enter a valid amount and currency.');$dueAt=self::dateValue($due);$pdo=Database::connection();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT sh.shipment_id,l.customer_company_id FROM shipments sh JOIN loads l ON l.load_id=sh.load_id LEFT JOIN payments p ON p.shipment_id=sh.shipment_id WHERE sh.shipment_id=? AND sh.current_status='delivered' AND p.payment_id IS NULL FOR UPDATE");$st->execute([$shipment]);$r=$st->fetch();if(!$r)throw new RuntimeException('Only an unpaid delivered shipment may be billed.');$pdo->prepare("INSERT INTO payments(payment_ref,payer_company_id,shipment_id,currency,requested_amount,received_amount,payment_status,due_at,idempotency_key,status,created_by_user_id,updated_by_user_id)VALUES(?,?,?,?,?,0,'requested',?,?, 'active',?,?)")->execute([Reference::make('PAY'),$r['customer_company_id'],$shipment,$currency,$amount,$dueAt,'PAY-'.bin2hex(random_bytes(16)),$uid,$uid]);$id=(int)$pdo->lastInsertId();self::event($pdo,$id,'requested',null,'requested',$amount,$currency,null,'Customer payment requested',$uid);self::audit($pdo,'PAYMENT_REQUESTED',$id,$uid,['shipment_id'=>$shipment,'amount'=>$amount]);NotificationService::send($pdo,NotificationService::usersForCompany($pdo,(int)$r['customer_company_id']),'payment','Payment requested','A '.$currency.' '.number_format($amount,2).' payment has been requested.','payments/index.php','payment',$id,$uid,'high');$pdo->commit();}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function submitPayment(int$id,string$method,string$ref,float$amount,string$notes,int$uid):void{if(!Auth::can('PAYMENT_SUBMIT_SHIPPER'))throw new RuntimeException('Payment submission permission required.');if($ref===''||$amount<=0)throw new RuntimeException('Transaction reference and amount are required.');$companies=array_map(fn($c)=>(int)$c['company_id'],Auth::context()['companies']??[]);$pdo=Database::connection();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT * FROM payments WHERE payment_id=? FOR UPDATE");$st->execute([$id]);$p=$st->fetch();if(!$p||!in_array((int)$p['payer_company_id'],$companies,true)||!in_array($p['payment_status'],['requested','rejected'],true))throw new RuntimeException('Payment cannot be submitted.');$pdo->prepare("UPDATE payments SET payment_status='submitted',payment_method=?,transaction_reference=?,received_amount=?,submitted_at=UTC_TIMESTAMP(6),submitted_by_user_id=?,payment_notes=?,updated_by_user_id=?,row_version=row_version+1 WHERE payment_id=?")->execute([$method,$ref,$amount,$uid,trim($notes)?:null,$uid,$id]);self::event($pdo,$id,'submitted',$p['payment_status'],'submitted',$amount,$p['currency'],$ref,$notes,$uid);self::audit($pdo,'PAYMENT_SUBMITTED',$id,$uid,['transaction_reference'=>$ref]);NotificationService::send($pdo,NotificationService::usersForRole($pdo,'MCCOLLIN_FINANCE'),'payment','Payment submitted','A customer payment is awaiting Finance review.','finance/index.php','payment',$id,$uid,'high');$pdo->commit();}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function reviewPayment(int$id,string$decision,float$amount,string$notes,int$uid):void{self::finance('PAYMENT_MANAGE_FINANCE');if(!in_array($decision,['confirmed','rejected'],true))throw new RuntimeException('Invalid payment decision.');if($decision==='rejected'&&trim($notes)==='')throw new RuntimeException('A rejection reason is required.');$pdo=Database::connection();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT * FROM payments WHERE payment_id=? FOR UPDATE");$st->execute([$id]);$p=$st->fetch();if(!$p||$p['payment_status']!=='submitted')throw new RuntimeException('Only submitted payments may be reviewed.');$received=$decision==='confirmed'?($amount>0?$amount:(float)$p['received_amount']):(float)$p['received_amount'];$extra=$decision==='confirmed'?",confirmed_at=UTC_TIMESTAMP(6),confirmed_by_user_id=".(int)$uid:'';$pdo->exec("UPDATE payments SET payment_status=".$pdo->quote($decision).",received_amount=".$pdo->quote((string)$received).",payment_notes=".$pdo->quote(trim($notes)).$extra.",updated_by_user_id=".(int)$uid.",row_version=row_version+1 WHERE payment_id=".(int)$id);self::event($pdo,$id,$decision,$p['payment_status'],$decision,$received,$p['currency'],$p['transaction_reference'],$notes,$uid);self::audit($pdo,'PAYMENT_'.strtoupper($decision),$id,$uid,['received_amount'=>$received]);NotificationService::send($pdo,NotificationService::usersForCompany($pdo,(int)$p['payer_company_id']),'payment','Payment '.$decision,'Your payment record was '.$decision.'.','payments/index.php','payment',$id,$uid,$decision==='rejected'?'high':'normal');$pdo->commit();}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function createSettlement(int$payment,float$gross,float$deduction,string$due,string$notes,int$uid):void{self::finance('SETTLEMENT_MANAGE_FINANCE');if($gross<=0||$deduction<0||$deduction>$gross)throw new RuntimeException('Enter valid settlement amounts.');$pdo=Database::connection();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT p.*,sh.active_assignment_id,a.carrier_company_id,a.carrier_user_id FROM payments p JOIN shipments sh ON sh.shipment_id=p.shipment_id JOIN assignments a ON a.assignment_id=sh.active_assignment_id LEFT JOIN settlements s ON s.payment_id=p.payment_id WHERE p.payment_id=? AND p.payment_status='confirmed' AND s.settlement_id IS NULL FOR UPDATE");$st->execute([$payment]);$r=$st->fetch();if(!$r)throw new RuntimeException('A settlement requires a confirmed unsettled payment.');$pdo->prepare("INSERT INTO settlements(settlement_ref,payment_id,shipment_id,carrier_company_id,carrier_user_id,currency,gross_amount,deduction_amount,net_amount,settlement_status,due_at,settlement_notes,status,created_by_user_id,updated_by_user_id)VALUES(?,?,?,?,?,?,?,?,?,'draft',?,?,'active',?,?)")->execute([Reference::make('SET'),$payment,$r['shipment_id'],$r['carrier_company_id'],$r['carrier_user_id'],$r['currency'],$gross,$deduction,$gross-$deduction,self::dateValue($due),trim($notes)?:null,$uid,$uid]);$sid=(int)$pdo->lastInsertId();self::history($pdo,'settlement',$sid,null,'draft',$uid,'Carrier settlement created');self::audit($pdo,'SETTLEMENT_CREATED',$sid,$uid,['payment_id'=>$payment,'net_amount'=>$gross-$deduction]);$notify=$r['carrier_user_id']?[(int)$r['carrier_user_id']]:NotificationService::usersForCompany($pdo,(int)$r['carrier_company_id']);NotificationService::send($pdo,$notify,'settlement','Settlement created','A carrier settlement has been created.','carrier/settlements/index.php','settlement',$sid,$uid,'normal');$pdo->commit();}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function settlementAction(int$id,string$to,string$method,string$ref,string$notes,int$uid):void{self::finance('SETTLEMENT_MANAGE_FINANCE');if(!in_array($to,['approved','paid'],true))throw new RuntimeException('Invalid settlement action.');$pdo=Database::connection();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT * FROM settlements WHERE settlement_id=? FOR UPDATE");$st->execute([$id]);$s=$st->fetch();$allowed=['draft'=>'approved','approved'=>'paid'];if(!$s||($allowed[$s['settlement_status']]??null)!==$to)throw new RuntimeException('Invalid settlement transition.');if($to==='paid'&&$ref==='')throw new RuntimeException('Payout transaction reference is required.');$extra=$to==='approved'?",approved_at=UTC_TIMESTAMP(6),approved_by_user_id=".(int)$uid:'';$pdo->exec("UPDATE settlements SET settlement_status=".$pdo->quote($to).$extra.",updated_by_user_id=".(int)$uid.",row_version=row_version+1 WHERE settlement_id=".(int)$id);if($to==='paid')$pdo->prepare("INSERT INTO payouts(payout_ref,settlement_id,beneficiary_company_id,beneficiary_user_id,amount,currency,payout_status,payment_method,transaction_reference,paid_at,paid_by_user_id,payout_notes,status,created_by_user_id,updated_by_user_id)VALUES(?,?,?,?,?,?,'paid',?,?,UTC_TIMESTAMP(6),?,?,'active',?,?)")->execute([Reference::make('PYO'),$id,$s['carrier_company_id'],$s['carrier_user_id'],$s['net_amount'],$s['currency'],$method,$ref,$uid,trim($notes)?:null,$uid,$uid]);self::history($pdo,'settlement',$id,$s['settlement_status'],$to,$uid,'Carrier settlement '.$to);self::audit($pdo,'SETTLEMENT_'.strtoupper($to),$id,$uid,['transaction_reference'=>$ref?:null]);$notify=$s['carrier_user_id']?[(int)$s['carrier_user_id']]:NotificationService::usersForCompany($pdo,(int)$s['carrier_company_id']);NotificationService::send($pdo,$notify,'settlement','Settlement '.$to,'Your carrier settlement is now '.$to.'.','carrier/settlements/index.php','settlement',$id,$uid,$to==='paid'?'high':'normal');$pdo->commit();}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 private static function event(PDO$p,int$id,string$type,?string$old,string$new,float$amount,string$currency,?string$ref,string$notes,int$uid):void{$p->prepare("INSERT INTO payment_events(payment_event_ref,payment_id,event_type,previous_status,new_status,amount,currency,transaction_reference,event_notes,occurred_at,actor_user_id,status,created_by_user_id,updated_by_user_id)VALUES(?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP(6),?,'active',?,?)")->execute([Reference::make('PEV'),$id,$type,$old,$new,$amount,$currency,$ref,trim($notes)?:null,$uid,$uid,$uid]);}
 private static function history(PDO$p,string$e,int$i,?string$o,string$n,int$u,string$r):void{$p->prepare("INSERT INTO status_history(status_history_ref,entity_type,entity_id_value,previous_status,new_status,actor_user_id,source_channel,reason,occurred_at,status,created_by_user_id)VALUES(?,?,?,?,?,?,'web',?,UTC_TIMESTAMP(6),'active',?)")->execute([Reference::make('STH'),$e,$i,$o,$n,$u,$r,$u]);}
 private static function audit(PDO$p,string$a,int$i,int$u,array$x):void{$p->prepare("INSERT INTO audit_events(audit_event_ref,metadata_json,status,created_by_user_id)VALUES(?,?,'active',?)")->execute([Reference::make('AUD'),json_encode(array_merge(['action_code'=>$a,'entity_id'=>$i],$x)),$u]);}
 private static function dateValue(string$v):string{$t=strtotime($v);if(!$t)throw new RuntimeException('Enter a valid date.');return gmdate('Y-m-d H:i:s',$t);}
}